-- Trusted task publishing.
--
-- The catalog UI is a convenience, not an authorization boundary. A browser
-- could previously insert arbitrary copy while claiming a reviewed template,
-- mark that copy youth-eligible, or leave a public listing behind when the
-- separate private-address insert failed. This migration moves the complete
-- publishing decision into one fixed-search-path SECURITY DEFINER function.
--
-- Approved catalog rows are selected from a mechanically generated private
-- allowlist. The allowlist is generated from src/taskCatalog.ts and contains
-- all 200 reviewed templates and all 858 finite option combinations. Custom
-- requests take a separate, permanently review-pending path with the same
-- bounded categories, durations, completions, and prohibited-work vocabulary
-- as the client. The caller supplies no owner, public copy, category label,
-- youth flag, review flag, approximate coordinates, or display area. The one
-- caller-selected public value is helper pay: NULL for Community Help, or a
-- bounded whole-dollar amount for paid and sponsored work.

create table private.task_catalog_categories (
  category_id text primary key,
  category text not null,
  boundary text not null,
  base_excluded text not null
);

create table private.task_catalog_variants (
  template_id text not null,
  variant_id text not null,
  selections jsonb not null,
  title text not null,
  description text not null,
  included text not null,
  excluded text not null,
  completion text not null,
  category_id text not null
    references private.task_catalog_categories (category_id),
  category text not null,
  duration_minutes integer not null
    check (duration_minutes between 15 and 240),
  suggested_pay integer not null
    check (suggested_pay >= 15),
  allowed_modes text[] not null,
  youth_eligible boolean not null,
  primary key (template_id, variant_id),
  unique (template_id, selections),
  check (jsonb_typeof(selections) = 'object'),
  check (
    cardinality(allowed_modes) >= 1
    and allowed_modes <@ array['paid', 'community', 'sponsored']::text[]
  )
);

create table private.task_service_areas (
  area_id text primary key,
  area text not null,
  time_zone text not null,
  center_lat double precision not null,
  center_lng double precision not null,
  lat_span double precision not null check (lat_span > 0),
  lng_span double precision not null check (lng_span > 0)
);

create table private.task_custom_completions (
  completion_id text primary key,
  completion text not null
);

revoke all on table private.task_catalog_categories
  from public, anon, authenticated, service_role;
revoke all on table private.task_catalog_variants
  from public, anon, authenticated, service_role;
revoke all on table private.task_service_areas
  from public, anon, authenticated, service_role;
revoke all on table private.task_custom_completions
  from public, anon, authenticated, service_role;

-- Generated catalog seed. Do not hand-edit: regenerate it from
-- src/taskCatalog.ts whenever the reviewed catalog changes.
insert into private.task_catalog_categories (
  category_id, category, boundary, base_excluded
)
values
  ('yard', 'Yard & garden', 'Ground level only — no ladders, roof access, tree climbing, power tools, or pesticide handling.', 'No ladder work, roof access, tree climbing, chemical spraying, or work above shoulder height.'),
  ('home', 'Home help', 'No electrical, gas, plumbing, roofing, or structural work, and nothing that needs a licence or a ladder above shoulder height.', 'No electrical, gas, plumbing, or structural work, and no ladder use above shoulder height.'),
  ('moving', 'Moving & hauling', 'Two-person lifts only for anything heavy — no solo lifting over 50 lb, no piano or safe moves, and no hazardous or unidentified materials.', 'No solo lifting over 50 lb, no pianos or safes, and no hazardous, chemical, or unidentified materials.'),
  ('cleaning', 'Cleaning', 'Standard household products only — no mixing chemicals, no biohazard or pest cleanup, and no exterior work needing a ladder.', 'No chemical mixing, biohazard or pest cleanup, mould remediation, or exterior work needing a ladder.'),
  ('errands', 'Errands & pickup', 'Prepaid orders only — no cash handling, no account or card access, no unplanned purchases, no passengers, and no prescription pickup.', 'No cash handling, card or account access, unplanned purchases, passengers, or prescription pickup.'),
  ('pets', 'Pets & animals', 'No veterinary or medical care, no medication dosing, no aggressive or unfamiliar animals, and no off-leash handling.', 'No veterinary or medical care, medication dosing, off-leash handling, or animals with a bite history.'),
  ('tech', 'Tech help', 'No passwords, banking, or account credentials are ever shared, no remote access, and no purchases on the requester''s behalf.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf.'),
  ('senior', 'Senior support', 'Practical and social help only — no personal care, no lifting or transferring a person, no medication of any kind, and no financial or legal decisions.', 'No personal or medical care, medication handling, lifting or transferring a person, or financial and legal decisions.'),
  ('events', 'Events & setup', 'No alcohol service, no crowd or door control, no cash handling, and no rigging, staging, or work at height.', 'No alcohol service, crowd or door control, cash handling, rigging, or work at height.'),
  ('access', 'Accessibility', 'The person directs the task throughout — no personal care, no physical support of a person''s weight, no handling of mobility equipment without direction, and no decisions made on their behalf.', 'No personal or medical care, no physically supporting a person''s weight, and no decisions made on the person''s behalf.'),
  ('learning', 'School & learning', 'Sessions with anyone under 18 happen in a public or supervised setting with a guardian present or on site — this is tutoring, never childcare or supervision.', 'No childcare or supervision responsibility, no unsupervised time with a minor, no transport of a minor, and no sitting exams or completing graded work for the student.'),
  ('mutual', 'Community & mutual aid', 'Volunteer neighbor help only — no professional services, no cash collection, no political or religious canvassing, and no work that a licensed trade should do.', 'No professional or licensed work, cash collection, canvassing, or anything a licensed trade should carry out.');

