  ('tech-app-help', 'pace=comfortable', '{"pace":"comfortable"}'::jsonb, 'Learn an app step by step', 'Walk through an app together at the owner''s pace and leave written steps. A normal working pace is fine.', 'A guided walkthrough and a written step-by-step card.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf.', 'The owner completes the task once unaided and has the written steps.', 'tech', 'Tech help', 60, 34, array['paid', 'community', 'sponsored']::text[], false),
  ('tech-tablet', 'pace=beginner', '{"pace":"beginner"}'::jsonb, 'Set up a tablet or e-reader', 'Set up the tablet or e-reader with the owner entering their own credentials. Please go slowly and explain each step.', 'Guided setup, accessibility settings, and a short walkthrough.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf.', 'The device is set up and the owner can use it unaided.', 'tech', 'Tech help', 75, 34, array['paid', 'community', 'sponsored']::text[], false),
  ('tech-tablet', 'pace=comfortable', '{"pace":"comfortable"}'::jsonb, 'Set up a tablet or e-reader', 'Set up the tablet or e-reader with the owner entering their own credentials. A normal working pace is fine.', 'Guided setup, accessibility settings, and a short walkthrough.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf.', 'The device is set up and the owner can use it unaided.', 'tech', 'Tech help', 60, 34, array['paid', 'community', 'sponsored']::text[], false),
  ('tech-accessibility', 'deviceCount=one', '{"deviceCount":"one"}'::jsonb, 'Turn on accessibility settings', 'Set up larger text, contrast, or screen reading on the owner''s devices. There is one device to work on.', 'Configuring accessibility settings and explaining how to change them later.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf.', 'The settings are applied and the owner can adjust them unaided.', 'tech', 'Tech help', 45, 30, array['paid', 'community', 'sponsored']::text[], false),
