  ('tech-cable-tidy', 'default', '{}'::jsonb, 'Tidy cables behind a desk or TV', 'Tidy and label the cables behind the desk or TV.', 'Routing, tying, and labelling the existing cables.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf. No rewiring, no work inside walls, and no new outlets.', 'The cables are tidy and labelled, and everything still works.', 'tech', 'Tech help', 45, 28, array['paid', 'community', 'sponsored']::text[], false),
  ('tech-desk-setup', 'tools=provided', '{"tools":"provided"}'::jsonb, 'Set up a desk or home office', 'Set up the desk, monitor, and peripherals so the workspace is ready to use. Hand tools are provided.', 'Assembly, connection, and a working test. Use of the provided hand tools.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf. No monitor wall mounting and no new electrical outlets.', 'The workspace is assembled and everything powers on.', 'tech', 'Tech help', 90, 48, array['paid', 'community', 'sponsored']::text[], false),
  ('tech-desk-setup', 'tools=bring', '{"tools":"bring"}'::jsonb, 'Set up a desk or home office', 'Set up the desk, monitor, and peripherals so the workspace is ready to use. Please bring your own hand tools.', 'Assembly, connection, and a working test. Helper''s own hand tools.', 'No password or credential sharing, banking or financial account access, remote-control software, or purchases on the requester''s behalf. No monitor wall mounting and no new electrical outlets.', 'The workspace is assembled and everything powers on.', 'tech', 'Tech help', 90, 54, array['paid', 'community', 'sponsored']::text[], false),
